:root {
  --bg: #1e1e2e;
  --card-bg: #2a2a3c;
  --primary: #7c5cff;
  --primary-hover: #9a7dff;
  --text: #e0e0f0;
  --text-muted: #a0a0b8;
  --border: #3a3a4c;
  --success: #4caf7a;
  --warning: #e0a040;
  --danger: #e05c5c;
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 32px 28px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.6rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.subtitle {
  color: var(--text-muted);
  margin-bottom: 24px;
  font-size: 0.95rem;
}

.control-group {
  margin-bottom: 20px;
}

label[for="length"] {
  display: block;
  margin-bottom: 8px;
  font-weight: 600;
}

input[type="range"] {
  width: 100%;
  height: 8px;
  -webkit-appearance: none;
  appearance: none;
  background: var(--border);
  border-radius: 4px;
  outline: none;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--primary);
  border: 2px solid var(--text);
  transition: background 0.15s;
}

input[type="range"]::-moz-range-thumb {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--primary);
  border: 2px solid var(--text);
  cursor: pointer;
}

input[type="range"]:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 4px;
}

input[type="range"]:hover::-webkit-slider-thumb {
  background: var(--primary-hover);
}

.toggles {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-bottom: 24px;
}

.toggle {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  -webkit-user-select: none;
  user-select: none;
}

.toggle input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.toggle-track {
  position: relative;
  display: inline-block;
  width: 48px;
  height: 26px;
  background: var(--border);
  border-radius: 13px;
  transition: background 0.2s;
  flex-shrink: 0;
}

.toggle-thumb {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  background: var(--text-muted);
  border-radius: 50%;
  transition: transform 0.2s, background 0.2s;
}

.toggle input:checked + .toggle-track {
  background: var(--primary);
}

.toggle input:checked + .toggle-track .toggle-thumb {
  transform: translateX(22px);
  background: #fff;
}

.toggle input:focus-visible + .toggle-track {
  outline: 2px solid var(--primary);
  outline-offset: 3px;
}

.toggle:hover .toggle-track {
  opacity: 0.9;
}

.toggle-label {
  font-size: 1rem;
}

.btn {
  display: block;
  width: 100%;
  padding: 14px;
  font-size: 1.05rem;
  font-weight: 700;
  font-family: inherit;
  color: #fff;
  background: var(--primary);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  margin-bottom: 24px;
}

.btn:hover {
  background: var(--primary-hover);
}

.btn:focus-visible {
  outline: 2px solid var(--text);
  outline-offset: 3px;
}

.btn:active {
  transform: scale(0.98);
}

.output-group label {
  display: block;
  font-weight: 600;
  margin-bottom: 8px;
}

.output-box {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px 16px;
  font-family: 'Courier New', monospace;
  font-size: 1.1rem;
  word-break: break-all;
  min-height: 52px;
  color: var(--text);
  margin-bottom: 10px;
  transition: border-color 0.2s;
}

.output-box:empty::before {
  content: 'Click Generate';
  color: var(--text-muted);
  font-style: italic;
}

.strength {
  font-weight: 600;
  font-size: 0.95rem;
}

.strength.weak { color: var(--danger); }
.strength.fair { color: var(--warning); }
.strength.good { color: var(--success); }
.strength.strong { color: var(--primary-hover); }

@media (max-width: 400px) {
  .card {
    padding: 24px 18px;
  }
  h1 {
    font-size: 1.35rem;
  }
}

const lengthInput = document.getElementById('length');
const lengthValue = document.getElementById('length-value');
const uppercaseToggle = document.getElementById('uppercase');
const numbersToggle = document.getElementById('numbers');
const symbolsToggle = document.getElementById('symbols');
const generateBtn = document.getElementById('generate');
const passwordOutput = document.getElementById('password-output');
const strengthLabel = document.getElementById('strength-label');

const LOWERCASE = 'abcdefghijklmnopqrstuvwxyz';
const UPPERCASE = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const NUMBERS = '0123456789';
const SYMBOLS = '!@#$%^&*()_+-=[]{}|;:,.<>?';

function getRandomChar(str) {
  return str[Math.floor(Math.random() * str.length)];
}

function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function generatePassword() {
  const length = parseInt(lengthInput.value, 10);
  const useUpper = uppercaseToggle.checked;
  const useNumbers = numbersToggle.checked;
  const useSymbols = symbolsToggle.checked;

  let pool = LOWERCASE;
  const required = [getRandomChar(LOWERCASE)];

  if (useUpper) {
    pool += UPPERCASE;
    required.push(getRandomChar(UPPERCASE));
  }
  if (useNumbers) {
    pool += NUMBERS;
    required.push(getRandomChar(NUMBERS));
  }
  if (useSymbols) {
    pool += SYMBOLS;
    required.push(getRandomChar(SYMBOLS));
  }

  const remaining = length - required.length;
  const chars = [...required];
  for (let i = 0; i < remaining; i++) {
    chars.push(getRandomChar(pool));
  }

  const password = shuffle(chars).join('');
  passwordOutput.textContent = password;
  updateStrength(length, useUpper, useNumbers, useSymbols);
}

function updateStrength(length, useUpper, useNumbers, useSymbols) {
  let score = 0;
  if (length >= 8) score++;
  if (length >= 12) score++;
  if (length >= 16) score++;
  if (length >= 24) score++;
  if (useUpper) score++;
  if (useNumbers) score++;
  if (useSymbols) score++;

  let label, cls;
  if (score <= 2) {
    label = 'Weak';
    cls = 'weak';
  } else if (score <= 4) {
    label = 'Fair';
    cls = 'fair';
  } else if (score <= 6) {
    label = 'Good';
    cls = 'good';
  } else {
    label = 'Strong';
    cls = 'strong';
  }

  strengthLabel.textContent = 'Strength: ' + label;
  strengthLabel.className = 'strength ' + cls;
}

lengthInput.addEventListener('input', () => {
  lengthValue.textContent = lengthInput.value;
});

generateBtn.addEventListener('click', generatePassword);

generatePassword();
